function sanitize(name: string): string {
  return name.toLowerCase().replace(/['"]/g, '').replace(/\s+/g, '-');
}

export function lookupBaseIcon(baseName: string): string | undefined {
  const key = sanitize(baseName);
  return BASE_ICON_MAP[key];
}
